import{_ as e,o,c as i,a2 as s}from"./chunks/framework.D7Ov6LBE.js";const h=JSON.parse('{"title":"Boas Práticas de Engenharia","description":"","frontmatter":{},"headers":[],"relativePath":"engenharia/boas-praticas.md","filePath":"engenharia/boas-praticas.md","lastUpdated":1786474711000}'),t={name:"engenharia/boas-praticas.md"};function d(r,a,n,l,c,p){return o(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="boas-praticas-de-engenharia" tabindex="-1">Boas Práticas de Engenharia <a class="header-anchor" href="#boas-praticas-de-engenharia" aria-label="Permalink to &quot;Boas Práticas de Engenharia&quot;">​</a></h1><p>Princípios e práticas aplicados no código-fonte, conforme <code>SOUL.md</code> (persona Chief Engineer) e <code>AGENTS.md</code>.</p><h2 id="_1-arquitetura-pragmatica" tabindex="-1">1. Arquitetura pragmática <a class="header-anchor" href="#_1-arquitetura-pragmatica" aria-label="Permalink to &quot;1. Arquitetura pragmática&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Princípio</th><th>Evidência no código</th></tr></thead><tbody><tr><td><strong>Estável &gt; trendy</strong></td><td>React + Dexie + Supabase — stack comprovada, sem modismos</td></tr><tr><td><strong>100% disponibilidade</strong></td><td>Offline-first: toda operação funciona sem rede</td></tr><tr><td><strong>Craftsmanship</strong></td><td>Componentes de responsabilidade única, tipagem estrita, código autodocumentado</td></tr><tr><td><strong>Antecipar gargalos</strong></td><td>Chunking (<code>React.lazy</code>), rotas protegidas, singleton lazy do Supabase</td></tr></tbody></table><h2 id="_2-padroes-aplicados" tabindex="-1">2. Padrões aplicados <a class="header-anchor" href="#_2-padroes-aplicados" aria-label="Permalink to &quot;2. Padrões aplicados&quot;">​</a></h2><h3 id="separacao-de-responsabilidades-soc" tabindex="-1">Separação de responsabilidades (SoC) <a class="header-anchor" href="#separacao-de-responsabilidades-soc" aria-label="Permalink to &quot;Separação de responsabilidades (SoC)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>components/  → UI pura (props + handlers)</span></span>
<span class="line"><span>stores/      → estado global (Zustand)</span></span>
<span class="line"><span>db/          → persistência (Dexie)</span></span>
<span class="line"><span>lib/         → integração cloud (Supabase)</span></span>
<span class="line"><span>utils/       → funções puras (formatação, fiscal)</span></span>
<span class="line"><span>types.ts     → contratos compartilhados</span></span></code></pre></div><h3 id="reatividade-sem-estado-duplicado" tabindex="-1">Reatividade sem estado duplicado <a class="header-anchor" href="#reatividade-sem-estado-duplicado" aria-label="Permalink to &quot;Reatividade sem estado duplicado&quot;">​</a></h3><ul><li><code>useLiveQuery</code> (Dexie hooks) = <strong>fonte única de verdade no banco local</strong>; a UI apenas reflete.</li><li>Zustand apenas para o que é global (usuário ativo, flag de sync, auth docs).</li></ul><h3 id="idempotencia-no-sync" tabindex="-1">Idempotência no sync <a class="header-anchor" href="#idempotencia-no-sync" aria-label="Permalink to &quot;Idempotência no sync&quot;">​</a></h3><ul><li><code>upsert ON CONFLICT (codigo_pedido | cpf_cnpj)</code> — reenvio nunca duplica.</li><li>Catálogo: upsert local por SKU.</li></ul><h3 id="auditoria-total" tabindex="-1">Auditoria total <a class="header-anchor" href="#auditoria-total" aria-label="Permalink to &quot;Auditoria total&quot;">​</a></h3><ul><li>Todo handler de mutação grava em <code>syncLogs</code> antes de retornar — rastreabilidade completa.</li></ul><h2 id="_3-tipagem-estrita" tabindex="-1">3. Tipagem estrita <a class="header-anchor" href="#_3-tipagem-estrita" aria-label="Permalink to &quot;3. Tipagem estrita&quot;">​</a></h2><ul><li>Contratos em <code>src/types.ts</code> (14 símbolos) usados por <strong>todas</strong> as camadas.</li><li>Enums fechados para domínios (categoria, pagamento, status sync/fiscal, tipo de log).</li><li><code>SyncLogType</code> com fallback <code>string</code> — extensível sem quebrar.</li></ul><h2 id="_4-qualidade-visual-e-acessibilidade" tabindex="-1">4. Qualidade visual e acessibilidade <a class="header-anchor" href="#_4-qualidade-visual-e-acessibilidade" aria-label="Permalink to &quot;4. Qualidade visual e acessibilidade&quot;">​</a></h2><ul><li>Tailwind CSS v4 com <strong>light theme de alto contraste (WCAG AA)</strong>.</li><li>Responsivo desktop/tablet/mobile — tablets são o dispositivo primário em campo.</li><li>Print styles dedicados (<code>@media print</code>) para cupom 80mm e DANFE A4.</li></ul><h2 id="_5-processo-e-protecao-do-repositorio" tabindex="-1">5. Processo e proteção do repositório <a class="header-anchor" href="#_5-processo-e-protecao-do-repositorio" aria-label="Permalink to &quot;5. Processo e proteção do repositório&quot;">​</a></h2><ul><li><code>.githooks/</code> — hooks de git (pre-commit) configurados via <code>prepare</code> script.</li><li><code>AGENTS.md</code> — regras para agentes de IA trabalharem no repo (padrões, validações, ordem de execução).</li><li><code>SOUL.md</code> — persona de engenharia (Chief Engineer) para consistência de decisões.</li><li>Docs em <code>docs/</code> com diagnóstico e plano de engenharia (docs/06) — <strong>a wiki herda esses documentos</strong>.</li></ul><h2 id="_6-melhorias-recomendadas-do-diagnostico-original" tabindex="-1">6. Melhorias recomendadas (do diagnóstico original) <a class="header-anchor" href="#_6-melhorias-recomendadas-do-diagnostico-original" aria-label="Permalink to &quot;6. Melhorias recomendadas (do diagnóstico original)&quot;">​</a></h2><p>Extraído de <code>docs/06-diagnostico-e-plano-de-engenharia.md</code>:</p><ul><li>Migrar auth mock (<code>ampla2026</code>, PINs) → <strong>Supabase Auth como hub único</strong> (OAuth para outros serviços) + RLS. Ver <a href="./../arquitetura/autenticacao">Autenticação &amp; Identidade</a>.</li><li>Substituir REST simulado de sync pelo middleware Adapter real (com retry/backoff e DLQ).</li><li>Automatizar testes E2E (Playwright) e unitários (Vitest) para os utils fiscais.</li><li>Service worker com fila persistente de sync (Background Sync).</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="./diagnostico-roadmap">Diagnóstico &amp; Roadmap</a></li><li><a href="./orquestracao-agentes">Orquestração de Agentes</a></li><li><a href="./../docs-legados/indice">Docs originais</a></li></ul>`,24)])])}const m=e(t,[["render",d]]);export{h as __pageData,m as default};
